<script lang="ts">
	/**
	 * Responsive image: <picture> with WebP srcset + resized JPEG srcset,
	 * original file as the fallback `src`. Variants are generated by
	 * scripts/gen-images.py as <stem>-<w>.jpg / .webp next to the original.
	 * `widths` must list the variants that exist for this image (never
	 * wider than the original — the original is appended as the top
	 * candidate). `sizes` must match the rendered CSS width (see
	 * web.dev / MDN responsive-images guidance).
	 * The <picture> uses display:contents so layout behaves exactly as
	 * if the <img> were alone — no visual change.
	 */
	interface Props {
		src: string;
		alt: string;
		width: number;
		height: number;
		sizes: string;
		widths?: number[];
		class?: string;
		loading?: 'lazy' | 'eager';
		fetchpriority?: 'high' | 'low' | 'auto';
	}
	const {
		src,
		alt,
		width,
		height,
		sizes,
		widths = [400, 800, 1200, 1600],
		class: cls = '',
		loading = 'lazy',
		fetchpriority = 'auto'
	}: Props = $props();

	const dot = $derived(src.lastIndexOf('.'));
	const base = $derived(src.slice(0, dot));
	const ext = $derived(src.slice(dot));
	const avail = $derived(widths.filter((w) => w < width));
	const webpSrcset = $derived(avail.map((w) => `${base}-${w}.webp ${w}w`).join(', '));
	const jpgSrcset = $derived(
		[...avail.map((w) => `${base}-${w}${ext} ${w}w`), `${src} ${width}w`].join(', ')
	);
</script>

<picture class="contents">
	{#if webpSrcset}
		<source type="image/webp" srcset={webpSrcset} {sizes} />
	{/if}
	<img
		{src}
		srcset={jpgSrcset}
		{sizes}
		{alt}
		{width}
		{height}
		{loading}
		fetchpriority={fetchpriority}
		class={cls}
	/>
</picture>
